                {
                    id: 'speed_ten',
                    title: '闪电节奏',
                    description: '10 次 5 分钟内完成高分练习',
                    icon: '🌩️',
                    tier: 3
                },

                // --- Special Achievements ---
                {
                    id: 'first_step',
                    title: '迈出第一步',
                    description: '完成第一次练习',
                    icon: '🌱',
                    tier: 1
                },
                {
                    id: 'accuracy_perfect',
                    title: '神射手',
                    description: '单次练习获得 100% 正确率',
                    icon: '🎯',
                    tier: 3
                },
                {
                    id: 'speed_demon',
                    title: '唯快不破',
                    description: '5分钟内完成高分练习',
                    icon: '⚡',
                    tier: 3
                }
